use crate::{primitives::*, workspace::*};
use leptos::prelude::*;
use serde_json::json;
#[component]
pub fn DemoView() -> impl IntoView {
    let ctx = expect_context::<WorkspaceContext>();
    let enabled = ctx.data.with_untracked(|v| v["scout"]["demo"] == true);
    let busy = RwSignal::new(None::<String>);
    let message = RwSignal::new(None::<(bool, String)>);
    if !enabled {
        return view!{<p role="status" class="rounded-xl border bg-card px-4 py-10 text-center text-sm text-muted-foreground">"Demo scenarios are switched off on this deployment (SCOUT_DEMO is not set)."</p>}.into_any();
    }
    view!{<section id="scout-demo" aria-labelledby="scout-demo-title" class="max-w-3xl space-y-4"><div><h1 id="scout-demo-title" class="text-xl font-medium tracking-tight">"Demo scenarios"</h1><p class="mt-1 text-sm text-muted-foreground">"Each scenario books one payment in the mocked bank. Scout then works it like a real one. Only shown with SCOUT_DEMO=1."</p></div><ul class="overflow-hidden rounded-xl border bg-card">{[("files","Invoice in files","A payment whose invoice sits on a company laptop."),("email","Invoice in email","The invoice arrived as an email attachment."),("chat_refund","Explained in chat","Someone already explained the payment on Slack."),("nowhere","Nowhere → ask on Slack","No document anywhere: Scout asks the person who paid."),("overspend_chat","Overspend approved in chat","A team goes over budget; the approval is in chat."),("ksef","Invoice only in KSeF","The invoice exists only in the Polish e-invoicing system."),("poisoned","Poisoned invoice (guardrails)","A supplier PDF carries an instruction for the AI: it goes to the owner's approval card.")].into_iter().map(move|(scenario,label,description)|view!{<li class="flex items-center gap-4 border-b px-4 py-2.5 last:border-b-0"><span class="min-w-0 flex-1"><span class="block text-[13px] font-medium">{label}</span><span class="block text-xs text-muted-foreground">{description}</span></span><button id=format!("scout-demo-{scenario}") type="button" class=button_classes(OUTLINE,"relative h-8 w-24 shrink-0 px-3") disabled=move||busy.get().is_some() aria-busy=move||busy.with(|v|v.as_deref()==Some(scenario)).to_string() on:click=move|_|{busy.set(Some(scenario.into()));message.set(None);leptos::task::spawn_local(async move{let result=json_request("/api/demo","POST",Some(&json!({"scenario":scenario})),Some(&ctx.slug.get_value())).await;busy.set(None);let ok=result.is_ok_and(|(code,_)|code<400);message.set(Some((ok,if ok{format!("Played “{label}”. Scout picks it up within seconds.")}else{"The demo scenario could not be started.".into()})));ctx.refresh();});}><span class=move||if busy.with(|v|v.as_deref()==Some(scenario)){"invisible flex items-center gap-1.5"}else{"flex items-center gap-1.5"}>"▷ Play"</span><Show when=move||busy.with(|v|v.as_deref()==Some(scenario))><span class="absolute inset-0 flex items-center justify-center gap-1.5"><span class="motion-safe:animate-spin"><Icon name="refresh"/></span>"Playing…"</span></Show></button></li>}).collect_view()}</ul><p id="scout-demo-status" role="status" class=move||if message.with(|v|v.as_ref().is_some_and(|v|!v.0)){"min-h-5 text-sm text-danger"}else{"min-h-5 text-sm text-muted-foreground"}>{move||message.get().map(|(ok,text)|view!{{text}{ok.then(||view!{<a href="#tasks" class="ml-1 text-foreground underline underline-offset-2">"Watch it in Tasks"</a>})}})}</p></section>}.into_any()
}
